[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>CommerceForge Dev Docs</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --bg-primary: #0d1117;
      --bg-secondary: #161b22;
      --bg-tertiary: #21262d;
      --border: #30363d;
      --text-primary: #f0f6fc;
      --text-secondary: #8b949e;
      --text-muted: #6e7681;
      --accent: #00ff88;
      --accent-secondary: #00d4ff;
      --accent-dim: rgba(0, 255, 136, 0.1);
      --font-body: 'Inter', system-ui, -apple-system, sans-serif;
      --font-mono: 'JetBrains Mono', 'Fira Code', monospace;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: var(--font-body);
      background: var(--bg-primary);
      color: var(--text-primary);
      line-height: 1.6;
      min-height: 100vh;
    }

    a { color: var(--accent-secondary); text-decoration: none; transition: color 0.2s; }
    a:hover { color: var(--accent); }

    /* Navigation */
    .nav {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      height: 64px;
      background: rgba(13, 17, 23, 0.95);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--border);
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 2rem;
      z-index: 1000;
    }

    .nav-brand {
      font-size: 1.25rem;
      font-weight: 700;
      color: var(--text-primary);
    }

    .nav-brand span { color: var(--accent); }

    .nav-links {
      display: flex;
      gap: 2rem;
      list-style: none;
    }

    .nav-links a {
      color: var(--text-secondary);
      font-size: 0.9rem;
      font-weight: 500;
      transition: color 0.2s;
    }

    .nav-links a:hover, .nav-links a.active { color: var(--text-primary); }

    .nav-actions {
      display: flex;
      align-items: center;
      gap: 1rem;
    }

    .nav-search {
      background: var(--bg-secondary);
      border: 1px solid var(--border);
      border-radius: 6px;
      padding: 0.5rem 1rem;
      color: var(--text-muted);
      font-size: 0.875rem;
      width: 200px;
    }

    .btn {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      padding: 0.6rem 1.2rem;
      border-radius: 6px;
      font-size: 0.875rem;
      font-weight: 500;
      cursor: pointer;
      transition: all 0.2s;
      border: none;
    }

    .btn-primary {
      background: var(--accent);
      color: #0d1117;
    }

    .btn-primary:hover { background: #00e07a; color: #0d1117; }

    .btn-secondary {
      background: transparent;
      border: 1px solid var(--border);
      color: var(--text-primary);
    }

    .btn-secondary:hover { border-color: var(--accent); color: var(--accent); }

    .btn-ghost {
      background: transparent;
      color: var(--text-secondary);
    }

    .btn-ghost:hover { color: var(--text-primary); background: var(--bg-tertiary); }

    /* Main content */
    main { padding-top: 64px; }

    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 2rem;
    }

    section { padding: 5rem 0; }

    /* Hero */
    .hero {
      text-align: center;
      padding: 8rem 0 6rem;
      background: linear-gradient(180deg, rgba(0,255,136,0.03) 0%, transparent 100%);
    }

    .hero h1 {
      font-size: 3.5rem;
      font-weight: 700;
      margin-bottom: 1.5rem;
      letter-spacing: -0.02em;
    }

    .hero h1 span {
      background: linear-gradient(135deg, var(--accent), var(--accent-secondary));
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .hero p {
      font-size: 1.25rem;
      color: var(--text-secondary);
      max-width: 700px;
      margin: 0 auto 2.5rem;
      line-height: 1.7;
    }

    .hero-cta {
      display: flex;
      justify-content: center;
      gap: 1rem;
      flex-wrap: wrap;
    }

    /* Product Cards */
    .product-cards {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 1.5rem;
      margin-top: 3rem;
    }

    .product-card {
      background: var(--bg-secondary);
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 2rem;
      transition: all 0.3s;
      position: relative;
      overflow: hidden;
    }

    .product-card::before {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      height: 3px;
      background: linear-gradient(90deg, var(--accent), var(--accent-secondary));
      opacity: 0;
      transition: opacity 0.3s;
    }

    .product-card:hover {
      border-color: var(--accent);
      transform: translateY(-4px);
      box-shadow: 0 12px 40px rgba(0, 255, 136, 0.1);
    }

    .product-card:hover::before { opacity: 1; }

    .product-icon {
      width: 48px;
      height: 48px;
      border-radius: 10px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.5rem;
      margin-bottom: 1.5rem;
    }

    .product-card.apps .product-icon { background: rgba(0, 255, 136, 0.15); }
    .product-card.storefronts .product-icon { background: rgba(0, 212, 255, 0.15); }
    .product-card.agents .product-icon { background: rgba(168, 85, 247, 0.15); }

    .product-card h3 {
      font-size: 1.25rem;
      margin-bottom: 0.75rem;
      font-weight: 600;
    }

    .product-card p {
      color: var(--text-secondary);
      font-size: 0.9rem;
      margin-bottom: 1.5rem;
      line-height: 1.6;
    }

    .product-card .card-link {
      color: var(--accent);
      font-size: 0.875rem;
      font-weight: 500;
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
    }

    .product-card .card-link:hover { gap: 0.75rem; }

    /* CLI Setup Section */
    .cli-section {
      background: var(--bg-secondary);
      border-top: 1px solid var(--border);
      border-bottom: 1px solid var(--border);
    }

    .cli-header {
      text-align: center;
      margin-bottom: 3rem;
    }

    .cli-header h2 {
      font-size: 2.25rem;
      margin-bottom: 1rem;
    }

    .cli-header p {
      color: var(--text-secondary);
      max-width: 600px;
      margin: 0 auto;
    }

    .cli-install {
      max-width: 800px;
      margin: 0 auto;
    }

    /* Package Manager Tabs */
    .pkg-tabs {
      display: flex;
      gap: 0;
      margin-bottom: 1.5rem;
      border-radius: 8px;
      overflow: hidden;
      border: 1px solid var(--border);
      width: fit-content;
      margin-left: auto;
      margin-right: auto;
    }

    .pkg-tab {
      padding: 0.75rem 1.5rem;
      background: var(--bg-tertiary);
      border: none;
      color: var(--text-secondary);
      font-family: var(--font-mono);
      font-size: 0.875rem;
      cursor: pointer;
      transition: all 0.2s;
    }

    .pkg-tab:first-child { border-radius: 7px 0 0 7px; }
    .pkg-tab:last-child { border-radius: 0 7px 7px 0; }

    .pkg-tab:hover { color: var(--text-primary); }

    .pkg-tab.active {
      background: var(--accent);
      color: #0d1117;
      font-weight: 500;
    }

    .install-code {
      background: var(--bg-primary);
      border: 1px solid var(--border);
      border-radius: 8px;
      padding: 1.5rem 2rem;
      text-align: center;
      margin-bottom: 2rem;
    }

    .install-code code {
      font-family: var(--font-mono);
      font-size: 1.1rem;
      color: var(--accent);
    }

    /* Accordion */
    .accordion { display: flex; flex-direction: column; gap: 0.75rem; }

    .accordion-item {
      background: var(--bg-primary);
      border: 1px solid var(--border);
      border-radius: 10px;
      overflow: hidden;
    }

    .accordion-trigger {
      width: 100%;
      padding: 1.25rem 1.5rem;
      background: transparent;
      border: none;
      color: var(--text-primary);
      font-size: 1rem;
      font-weight: 600;
      text-align: left;
      cursor: pointer;
      display: flex;
      justify-content: space-between;
      align-items: center;
      transition: background 0.2s;
    }

    .accordion-trigger:hover { background: var(--bg-secondary); }

    .accordion-trigger .chevron {
      transition: transform 0.3s;
      color: var(--text-muted);
    }

    .accordion-item.open .accordion-trigger .chevron { transform: rotate(180deg); }
    .accordion-item.open .accordion-trigger { color: var(--accent); }

    .accordion-content {
      max-height: 0;
      overflow: hidden;
      transition: max-height 0.3s ease-out;
    }

    .accordion-item.open .accordion-content { max-height: 500px; }

    .accordion-body {
      padding: 0 1.5rem 1.5rem;
    }

    .accordion-body ol {
      padding-left: 1.5rem;
      color: var(--text-secondary);
    }

    .accordion-body li {
      margin-bottom: 0.75rem;
      line-height: 1.6;
    }

    .accordion-body code {
      font-family: var(--font-mono);
      background: var(--bg-tertiary);
      padding: 0.2rem 0.5rem;
      border-radius: 4px;
      font-size: 0.875rem;
      color: var(--accent-secondary);
    }

    .accordion-body .cmd {
      background: var(--bg-tertiary);
      border: 1px solid var(--border);
      border-radius: 6px;
      padding: 0.75rem 1rem;
      margin-top: 1rem;
      font-family: var(--font-mono);
      font-size: 0.9rem;
      color: var(--text-primary);
    }

    /* Launch CTA */
    .launch-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 1.5rem;
    }

    .launch-card {
      background: var(--bg-secondary);
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 2rem;
      position: relative;
      overflow: hidden;
    }

    .launch-card::after {
      content: '';
      position: absolute;
      top: -50%;
      right: -50%;
      width: 100%;
      height: 100%;
      background: radial-gradient(circle, rgba(0,255,136,0.05) 0%, transparent 70%);
      pointer-events: none;
    }

    .launch-card h3 {
      font-size: 1.25rem;
      margin-bottom: 0.75rem;
    }

    .launch-card p {
      color: var(--text-secondary);
      font-size: 0.9rem;
      margin-bottom: 1.25rem;
    }

    /* Community */
    .community-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 1rem;
    }

    .community-card {
      background: var(--bg-secondary);
      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 1.5rem;
      text-align: center;
      transition: all 0.2s;
    }

    .community-card:hover {
      border-color: var(--accent);
      transform: translateY(-2px);
    }

    .community-card h4 {
      font-size: 0.95rem;
      margin-bottom: 0.5rem;
    }

    .community-card p {
      color: var(--text-muted);
      font-size: 0.8rem;
    }

    /* Footer */
    footer {
      background: var(--bg-secondary);
      border-top: 1px solid var(--border);
      padding: 4rem 0 2rem;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 3rem;
      margin-bottom: 3rem;
    }

    .footer-col h4 {
      color: var(--text-primary);
      font-size: 0.9rem;
      font-weight: 600;
      margin-bottom: 1.25rem;
    }

    .footer-col ul { list-style: none; }

    .footer-col li { margin-bottom: 0.75rem; }

    .footer-col a {
      color: var(--text-muted);
      font-size: 0.875rem;
    }

    .footer-col a:hover { color: var(--accent); }

    .footer-bottom {
      border-top: 1px solid var(--border);
      padding-top: 2rem;
      display: flex;
      justify-content: space-between;
      align-items: center;
    }

    .footer-bottom p {
      color: var(--text-muted);
      font-size: 0.8rem;
    }

    /* Section titles */
    .section-label {
      text-transform: uppercase;
      font-size: 0.75rem;
      font-weight: 600;
      color: var(--accent);
      letter-spacing: 0.1em;
      margin-bottom: 0.75rem;
    }

    .section-title {
      font-size: 2rem;
      font-weight: 700;
      margin-bottom: 1rem;
    }

    .section-subtitle {
      color: var(--text-secondary);
      font-size: 1.1rem;
      max-width: 600px;
    }

    .text-center { text-align: center; }
    .mx-auto { margin-left: auto; margin-right: auto; }

    /* Responsive */
    @media (max-width: 1024px) {
      .product-cards { grid-template-columns: repeat(2, 1fr); }
      .community-grid { grid-template-columns: repeat(2, 1fr); }
      .footer-grid { grid-template-columns: repeat(2, 1fr); }
    }

    @media (max-width: 768px) {
      .nav-links { display: none; }
      .hero h1 { font-size: 2.5rem; }
      .product-cards { grid-template-columns: 1fr; }
      .launch-grid { grid-template-columns: 1fr; }
      .community-grid { grid-template-columns: 1fr; }
      .footer-grid { grid-template-columns: 1fr; }
      .footer-bottom { flex-direction: column; gap: 1rem; text-align: center; }
      .pkg-tabs { width: 100%; }
      .pkg-tab { flex: 1; text-align: center; }
    }
  </style>
</head>
<body>
  <nav class="nav">
    <div class="nav-brand">Commerce<span>Forge</span> Dev Docs</div>
    <ul class="nav-links">
      <li><a href="apps-build.html">Apps</a></li>
      <li><a href="storefronts.html">Storefronts</a></li>
      <li><a href="agents.html">Agents</a></li>
      <li><a href="#">References</a></li>
      <li><a href="support.html">Help</a></li>
    </ul>
    <div class="nav-actions">
      <input type="text" class="nav-search" placeholder="Search docs...">
      <button class="btn btn-secondary">Log in</button>
    </div>
  </nav>

  <main>
    <section class="hero">
      <div class="container">
        <h1><span>CommerceForge</span> Dev Docs</h1>
        <p>Learn how to build an app, or customize your storefront. Whether you're just getting started, deep in the development process, or ready to distribute and monetize your work, CommerceForge's docs, dev tools and frameworks make building easy and efficient.</p>
        <div class="hero-cta">
          <a href="apps-build.html" class="btn btn-primary">Build your first app →</a>
          <a href="storefronts.html" class="btn btn-secondary">Build a storefront →</a>
          <a href="agents.html" class="btn btn-secondary">Build agents with UCP →</a>
        </div>

        <div class="product-cards">
          <div class="product-card apps">
            <div class="product-icon">⚡</div>
            <h3>Apps</h3>
            <p>Extend CommerceForge's core functionality with apps that integrate into the admin, online store, checkout and more.</p>
            <a href="apps-build.html" class="card-link">Build your first app →</a>
          </div>
          <div class="product-card storefronts">
            <div class="product-icon">🎨</div>
            <h3>Storefronts</h3>
            <p>Help merchants express their unique brand by building a custom theme or Hydrogen storefront.</p>
            <a href="storefronts.html" class="card-link">Build a storefront →</a>
          </div>
          <div class="product-card agents">
            <div class="product-icon">🤖</div>
            <h3>Agents</h3>
            <p>Build agentic shopping experiences powered by CommerceForge merchants, from product discovery to checkout.</p>
            <a href="agents.html" class="card-link">Build agents with UCP →</a>
          </div>
        </div>
      </div>
    </section>

    <section class="cli-section">
      <div class="container">
        <div class="cli-header">
          <div class="section-label">Quick Start</div>
          <h2>Accelerate development with CommerceForge CLI 3.0</h2>
          <p class="section-subtitle mx-auto">Initialize new apps, themes, and headless storefronts in an instant with the latest CommerceForge CLI. A single command installs all the dependencies you need.</p>
        </div>

        <div class="cli-install">
          <div class="pkg-tabs">
            <button class="pkg-tab active" data-pkg="npm">npm</button>
            <button class="pkg-tab" data-pkg="yarn">yarn</button>
            <button class="pkg-tab" data-pkg="pnpm">pnpm</button>
          </div>

          <div class="install-code">
            <code id="install-command">npm i -g @commerceforge/cli@latest</code>
          </div>

          <div class="accordion">
            <div class="accordion-item">
              <button class="accordion-trigger">
                Apps
                <span class="chevron">▼</span>
              </button>
              <div class="accordion-content">
                <div class="accordion-body">
                  <ol>
                    <li>Install CommerceForge CLI globally using the command above.</li>
                    <li>Navigate to the directory where you want to create your app.</li>
                    <li>Run the init command to create a new app. Your app will be added as a new subdirectory.</li>
                  </ol>
                  <div class="cmd">commerceforge app init</div>
                </div>
              </div>
            </div>

            <div class="accordion-item">
              <button class="accordion-trigger">
                Themes
                <span class="chevron">▼</span>
              </button>
              <div class="accordion-content">
                <div class="accordion-body">
                  <ol>
                    <li>Install CommerceForge CLI globally using the command above.</li>
                    <li>Navigate to the directory where you want to create your theme.</li>
                    <li>Run the init command to clone a starter theme. Your theme will be created in a new subdirectory.</li>
                  </ol>
                  <div class="cmd">commerceforge theme init</div>
                </div>
              </div>
            </div>

            <div class="accordion-item">
              <button class="accordion-trigger">
                Headless Storefronts
                <span class="chevron">▼</span>
              </button>
              <div class="accordion-content">
                <div class="accordion-body">
                  <ol>
                    <li>Install CommerceForge CLI globally using the command above.</li>
                    <li>Navigate to the directory where you want to create your Hydrogen storefront.</li>
                    <li>Run the init command to initialize a Hydrogen storefront in a new subdirectory.</li>
                  </ol>
                  <div class="cmd">commerceforge hydrogen init</div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>

    <section>
      <div class="container">
        <div class="section-label text-center">Launch</div>
        <h2 class="section-title text-center">Ready to distribute?</h2>
        <p class="section-subtitle mx-auto text-center" style="margin-bottom: 3rem;">When you're ready, submit your work to the CommerceForge marketplace so merchants can find and buy your creations.</p>

        <div class="launch-grid">
          <div class="launch-card">
            <h3>App Marketplace</h3>
            <p>Submit your app to the CommerceForge App Marketplace so merchants can find and buy your app through search or personalized recommendations.</p>
            <a href="#" class="btn btn-primary">See App Marketplace requirements →</a>
          </div>
          <div class="launch-card">
            <h3>Theme Store</h3>
            <p>Promote and sell your custom theme to merchants building their brands on the CommerceForge Theme Store.</p>
            <a href="#" class="btn btn-primary">See Theme Store requirements →</a>
          </div>
        </div>
      </div>
    </section>

    <section style="padding-top: 0;">
      <div class="container">
        <div class="section-label text-center">Community</div>
        <h2 class="section-title text-center">Join the ecosystem</h2>
        <p class="section-subtitle mx-auto text-center" style="margin-bottom: 3rem;">Connect with developers and CommerceForge experts to share insights, ask questions, and collaborate.</p>

        <div class="community-grid">
          <div class="community-card">
            <h4>Dev Community</h4>
            <p>Q&A and advice from experts</p>
          </div>
          <div class="community-card">
            <h4>Developer Changelog</h4>
            <p>Latest ecosystem updates</p>
          </div>
          <div class="community-card">
            <h4>YouTube channel</h4>
            <p>Tips and insights in dev</p>
          </div>
          <div class="community-card">
            <h4>Partners blog</h4>
            <p>Educational resources</p>
          </div>
        </div>
      </div>
    </section>
  </main>

  <footer>
    <div class="container">
      <div class="footer-grid">
        <div class="footer-col">
          <h4>Updates</h4>
          <ul>
            <li><a href="#">Developer changelog</a></li>
            <li><a href="#">CommerceForge Editions</a></li>
          </ul>
        </div>
        <div class="footer-col">
          <h4>Business growth</h4>
          <ul>
            <li><a href="#">CommerceForge Partners Program</a></li>
            <li><a href="#">CommerceForge App Marketplace</a></li>
            <li><a href="#">CommerceForge Academy</a></li>
          </ul>
        </div>
        <div class="footer-col">
          <h4>Legal</h4>
          <ul>
            <li><a href="#">Terms of service</a></li>
            <li><a href="#">API terms of use</a></li>
            <li><a href="#">Privacy policy</a></li>
            <li><a href="#">Partners Program Agreement</a></li>
          </ul>
        </div>
        <div class="footer-col">
          <h4>CommerceForge</h4>
          <ul>
            <li><a href="#">About CommerceForge</a></li>
            <li><a href="#">CommerceForge Plus</a></li>
            <li><a href="#">Careers</a></li>
            <li><a href="#">Investors</a></li>
            <li><a href="#">Press and media</a></li>
          </ul>
        </div>
      </div>
      <div class="footer-bottom">
        <p>© 2026 CommerceForge. All rights reserved.</p>
        <p>Built for developers who build the future of commerce.</p>
      </div>
    </div>
  </footer>

  <script>
    // Package manager tabs
    const pkgCommands = {
      npm: 'npm i -g @commerceforge/cli@latest',
      yarn: 'yarn global add @commerceforge/cli@latest',
      pnpm: 'pnpm add -g @commerceforge/cli@latest'
    };

    document.querySelectorAll('.pkg-tab').forEach(tab => {
      tab.addEventListener('click', () => {
        document.querySelectorAll('.pkg-tab').forEach(t => t.classList.remove('active'));
        tab.classList.add('active');
        document.getElementById('install-command').textContent = pkgCommands[tab.dataset.pkg];
      });
    });

    // Accordion - only one open at a time
